def longest_buildable_word(words):
    class Node:
        def __init__(self):
            self.children = {}
            self.is_word = False

    root = Node()
    for w in words:
        node = root
        for ch in w:
            if ch not in node.children:
                node.children[ch] = Node()
            node = node.children[ch]
        node.is_word = True

    best = ""

    def dfs(node, path):
        nonlocal best
        for ch in sorted(node.children):
            child = node.children[ch]
            if child.is_word:
                cand = path + ch
                if len(cand) > len(best) or (len(cand) == len(best) and cand < best):
                    best = cand
                dfs(child, cand)

    dfs(root, "")
    return best
